INSERT OR IGNORE INTO settings (key,value) VALUES ('content','{"headline": "The right people. The right support. Room to grow.", "headlineAr": "الكوادر المناسبة. الدعم المناسب. مجال للنمو.", "intro": "Recruitment, outsourcing, and staff augmentation tailored to your business—connecting companies with talent and people with opportunities.", "introAr": "حلول توظيف وتعهيد ودعم فرق تناسب احتياجات شركتك، وتربط الشركات بالكفاءات والأفراد بالفرص.", "about": "Founded by Samy Salama, Apex Global Services LLC connects businesses with the people and support they need to grow. Our focus spans recruitment, workforce sourcing and training partnerships, with outsourcing and staff augmentation expanding our service offering.", "aboutAr": "أسس سامي سلامة Apex Global Services LLC لربط الشركات بالكوادر والدعم الذي تحتاجه للنمو. يشمل تركيزنا التوظيف وتوفير القوى العاملة وشراكات التدريب، مع التوسع في خدمات التعهيد ودعم الفرق بالكوادر.", "email": "apexrecruitmentgroup1@gmail.com", "phone": "", "whatsapp": "", "linkedin": "", "facebook": "", "address": "Egypt & the MENA region", "addressAr": "مصر والشرق الأوسط وشمال أفريقيا"}');
